def state(net):
    return {name: tensor.detach().clone() for name, tensor in net.state_dict().items()}

def state_digest(values):
    h = hashlib.sha256()
    for name, value in values.items():
        h.update(name.encode()); h.update(str(tuple(value.shape)).encode())
        h.update(value.detach().contiguous().numpy().tobytes())
    return h.hexdigest()
